  function brand(name, cls) {
    var d = ICONS.brand[(name || '').toLowerCase()];
    if (!d) return ui('globe', cls);
    return '<svg class="' + (cls || 'icon') + '" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="' + d + '"/></svg>';
  }
  function ui(name, cls) {
    var inner = ICONS.ui[name] || ICONS.ui['link'];
    return '<svg class="' + (cls || 'icon') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + inner + '</svg>';
  }
  function social(name, cls) {
    var n = (name || '').toLowerCase();
    if (n === 'email' || n === 'mail') return ui('mail', cls);
    if (n === 'phone') return ui('phone', cls);
    if (n === 'website' || n === 'portfolio' || n === 'blog') return ui('globe', cls);
    return brand(n, cls);
  }
  window.Icons = { brand: brand, ui: ui, social: social, has: function (n) { return !!ICONS.brand[(n || '').toLowerCase()]; }, brandNames: Object.keys(ICONS.brand).sort(), uiNames: Object.keys(ICONS.ui).sort() };
